export async function listTools() {
  return [
    {
      name: 'events_list',
      description: 'List events in source order with optional cursor pagination.',
      inputSchema: {
        type: 'object',
        properties: {
          cursor: { type: 'string', description: 'Opaque cursor returned from a previous page.' },
          page_size: { type: 'integer', minimum: 1, maximum: 3, default: 2, description: 'Number of events per page (1-3, default 2).' }
        },
        additionalProperties: false
      }
    }
  ];
}

function encodeCursor(offset) {
  return Buffer.from(JSON.stringify({ i: offset }), 'utf8').toString('base64');
}

function decodeCursor(cursor) {
  let parsed;
  try {
    parsed = JSON.parse(Buffer.from(cursor, 'base64').toString('utf8'));
  } catch {
    throw new Error('Unknown cursor');
  }
  if (!parsed || typeof parsed !== 'object' || !Number.isInteger(parsed.i) || parsed.i < 0) {
