import crypto from 'node:crypto';
import events from './events.json' with {type:'json'};

const SECRET = 'event-page-mcp-secret';
const DEFAULT_PAGE_SIZE = 2;
const MIN_PAGE_SIZE = 1;
const MAX_PAGE_SIZE = 3;

export async function listTools() {
  return [
    {
      name: 'events_list',
      description: 'List events in source order with optional cursor pagination.',
      inputSchema: {
        type: 'object',
        properties: {
          cursor: { type: 'string', description: 'Opaque cursor returned from a previous call.' },
          page_size: { type: 'integer', minimum: MIN_PAGE_SIZE, maximum: MAX_PAGE_SIZE, default: DEFAULT_PAGE_SIZE, description: 'Number of events per page (1-3, default 2).' }
        },
        additionalProperties: false
      }
    }
  ];
}

function signOffset(offset) {
  const sig = crypto.createHmac('sha256', SECRET).update(String(offset)).digest('hex');
  return Buffer.from(JSON.stringify({ o: offset, s: sig })).toString('base64url');
}

function verifyCursor(cursor) {
  if (typeof cursor !== 'string' || cursor.length === 0) {
    throw new Error('Unknown cursor');
  }
  let parsed;
  try {
    parsed = JSON.parse(Buffer.from(cursor, 'base64url').toString('utf8'));
  } catch {
    throw new Error('Unknown cursor');
  }
  if (!parsed || typeof parsed !== 'object' || typeof parsed.o !== 'number' || !Number.isInteger(parsed.o) || typeof parsed.s !== 'string') {
    throw new Error('Unknown cursor');
  }
  const expected = crypto.createHmac('sha256', SECRET).update(String(parsed.o)).digest('hex');
  if (parsed.s.length !== expected.length || !crypto.timingSafeEqual(Buffer.from(parsed.s), Buffer.from(expected))) {
    throw new Error('Unknown cursor');
  }
  if (parsed.o < 0) {
    throw new Error('Unknown cursor');
  }
  return parsed.o;
}

export async function callTool(name, args) {
  if (name !== 'events_list') {
    throw new Error('Unknown tool: ' + name);
  }
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments');
  }

  const allowed = new Set(['cursor', 'page_size']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error('Unknown argument: ' + key);
    }
  }

  const { cursor, page_size } = args;

  let offset = 0;
  if (cursor !== undefined) {
    offset = verifyCursor(cursor);
  }

  let size = DEFAULT_PAGE_SIZE;
  if (page_size !== undefined) {
    if (typeof page_size !== 'number' || !Number.isInteger(page_size) || page_size < MIN_PAGE_SIZE || page_size > MAX_PAGE_SIZE) {
      throw new Error('page_size must be an integer from ' + MIN_PAGE_SIZE + ' to ' + MAX_PAGE_SIZE);
    }
    size = page_size;
  }

  const page = events.slice(offset, offset + size);
  const nextOffset = offset + size;
  const result = { events: page };
  if (nextOffset < events.length) {
    result.next_cursor = signOffset(nextOffset);
  }

  return { content: [{ type: 'text', text: JSON.stringify(result) }] };
}

